BasicBlockTemplateBuilder = Callable[[VarFactory, str | None], EmtModelTemplate]


def get_template_builder_by_module_name(module_name: str) -> BasicBlockTemplateBuilder | None:
    """Resolve one generated builder by its standalone module name.

    :param module_name: Standalone generated module stem.
    :return: Matching builder, or ``None`` when it is not registered.
    """
    builders_by_module_name: dict[str, BasicBlockTemplateBuilder] = get_template_builders_by_module_name()
    template_builder: BasicBlockTemplateBuilder | None = builders_by_module_name.get(module_name, None)
    return template_builder

