BASIC_BLOCKS_BY_KEY: dict[str, BasicBlockTemplateDescriptor] = {
    descriptor.template_key: descriptor
    for descriptors in BASIC_BLOCK_CATALOGUE.values()
    for descriptor in descriptors
}


def get_basic_block_catalog_descriptors() -> tuple[BasicBlockTemplateDescriptor, ...]:
    """Return the complete Engine-owned basic-block catalogue.

    :return: Basic-block descriptors in their declared category order.
    """
    return tuple(
        descriptor
        for descriptors in BASIC_BLOCK_CATALOGUE.values()
        for descriptor in descriptors
    )


def get_template_catalogue_entries(mode: DynamicSimulationMode) -> list[TemplateCatalogueEntry]:
    """Return entries in the explicitly declared category order."""
    catalogue: dict[str, list[TemplateCatalogueEntry]]
    if mode == DynamicSimulationMode.RMS:
        catalogue = RMS_TEMPLATE_CATALOGUE
    elif mode == DynamicSimulationMode.EMT:
        catalogue = EMT_TEMPLATE_CATALOGUE
    else:
        catalogue = dict()
    return [entry for entries in catalogue.values() for entry in entries]
